 es:{descriptor:'Colección musical',collection:'La colección',search:'Buscar canción',language:'Idioma de interpretación',all:'Todos',year:'Año de estreno',series:'Obra original',edition:'Edición de origen',jp:'JP',international:'INT',localization:'Localización',theme:'Tema',arc:'Arco',arrangement:'Versión de referencia',firstCover:'El primer cover publicado de Blaze Leiton',artistPending:'Créditos por verificar',multilingual:'Multilingüe',season:'Temporada',debut:'Primer estreno',context:'Contexto',versionDate:'Fecha de esta versión',grid:'Portadas',list:'Lista',versions:'versiones',back:'Volver a la colección',version:'Versión',lyrics:'Letra',pending:'Contenido en preparación.',credits:'Créditos',original:'Artista original',performance:'Interpretación',date:'Publicación',media:'Cover',download:'Descarga',related:'También en la colección',empty:'No hay coincidencias.',preview:'Vista previa · Colección en construcción',mediaPending:'Vídeo y descargas aún no habilitados.',footer:'Rebel Mix — Scripta Lyrica',clear:'Limpiar filtros'},
 en:{descriptor:'Music Collection',collection:'The collection',search:'Search songs',language:'Performance language',all:'All',year:'Debut year',series:'Original work',edition:'Source edition',jp:'JP',international:'INT',localization:'Localization',theme:'Theme',arc:'Story arc',arrangement:'Reference arrangement',firstCover:'Blaze Leiton’s first published cover',artistPending:'Credits pending verification',multilingual:'Multilingual',season:'Season',debut:'First release',context:'Context',versionDate:'Version release date',grid:'Covers',list:'List',versions:'versions',back:'Back to collection',version:'Version',lyrics:'Lyrics',pending:'Content in preparation.',credits:'Credits',original:'Original artist',performance:'Performance',date:'Published',media:'Cover',download:'Download',related:'Also in the collection',empty:'No matches.',preview:'Preview · Collection under construction',mediaPending:'Video and downloads not enabled yet.',footer:'Rebel Mix — Scripta Lyrica',clear:'Clear filters'},
 ja:{descriptor:'楽曲選集',collection:'楽曲一覧',search:'楽曲を検索',language:'歌唱言語',all:'すべて',year:'初公開年',series:'原作',edition:'原曲の版',jp:'日本版',international:'海外版',localization:'ローカライズ',theme:'主題歌',arc:'章',arrangement:'参考アレンジ',firstCover:'Blaze Leiton 初の公開カバー',artistPending:'クレジット確認中',multilingual:'多言語',season:'シーズン',debut:'初公開',context:'関連作品',versionDate:'バージョン公開日',grid:'ジャケット',list:'一覧',versions:'バージョン',back:'楽曲一覧に戻る',version:'バージョン',lyrics:'歌詞',pending:'準備中です。',credits:'クレジット',original:'原曲アーティスト',performance:'歌唱',date:'公開日',media:'カバー',download:'ダウンロード',related:'関連曲',empty:'該当する楽曲がありません。',preview:'プレビュー・制作中',mediaPending:'動画・ダウンロードは未公開です。',footer:'Rebel Mix — Scripta Lyrica',clear:'絞り込みを解除'}
